const GEO_SESSION_KEY='raluvaaaApproxPlaceV1';
function currentLanguage(){return state.lang==='en'?'en':'fr'}
function approximatePlaceFromAddress(a){
  const city=a?.city||a?.town||a?.village||a?.municipality||a?.borough||a?.county||'';
  const country=a?.country||'';
  return [city,country].filter(Boolean).join(', ')
}
async function reversePlace(lat,lon){
  const u=new URL('https://nominatim.openstreetmap.org/reverse');
  u.searchParams.set('format','jsonv2');u.searchParams.set('lat',String(lat));u.searchParams.set('lon',String(lon));u.searchParams.set('zoom','10');u.searchParams.set('addressdetails','1');u.searchParams.set('accept-language',currentLanguage());
  const res=await fetch(u.toString(),{headers:{Accept:'application/json'}});
  if(!res.ok)throw new Error('reverse_geocode_'+res.status);
  const data=await res.json();
  const place=approximatePlaceFromAddress(data?.address);
  if(!place)throw new Error('reverse_geocode_empty');
  return place
}
function prefillCurrentLocation(input,status){
  if(!input)return;
  let cached=null;try{cached=JSON.parse(sessionStorage.getItem(GEO_SESSION_KEY)||'null')}catch{}
  if(cached?.place&&Date.now()-(cached.at||0)<15*60*1000){input.value=cached.place;if(status)status.textContent=T('located');return}
  if(!navigator.geolocation){if(status)status.textContent=T('locationManual');return}
  if(status)status.textContent=T('locating');
  input.dataset.userEdited='0';
  input.addEventListener('input',()=>{input.dataset.userEdited='1'},{once:true});
  navigator.geolocation.getCurrentPosition(async pos=>{
    try{
      const place=await reversePlace(pos.coords.latitude,pos.coords.longitude);
      try{sessionStorage.setItem(GEO_SESSION_KEY,JSON.stringify({place,at:Date.now()}))}catch{}
      if(input.dataset.userEdited!=='1'&&!input.value.trim())input.value=place;
      if(status)status.textContent=T('located')
    }catch{if(status)status.textContent=T('locationManual')}
  },()=>{if(status)status.textContent=T('locationManual')},{enableHighAccuracy:false,timeout:6500,maximumAge:5*60*1000})
}
function esc(s){return String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))}
function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
