function actorByLineage(){const map=new Map();for(const e of state.events)if(e.type==='create'&&e.lineageId&&e.actorId)map.set(e.lineageId,e.actorId);return map}
function ownerActor(m){return actorByLineage().get(m?.lineageId)||null}
function owned(m){return ownerActor(m)===PERSONA}
