function respond(p,decision){if(!(p.requiredActors||[]).includes(PERSONA))return;if(responseFor(p.proposalId,PERSONA))return;commit({type:'proposal_response',proposalId:p.proposalId,decision,semanticId:p.semanticId,aSemanticId:p.aSemanticId,bSemanticId:p.bSemanticId});materialize(p);renderDrawer()}
function cancelProposal(p){if(!p||p.actorId!==PERSONA||proposalStatus(p)!=='pending')return;commit({type:'proposal_cancelled',proposalId:p.proposalId,semanticId:p.semanticId,aSemanticId:p.aSemanticId,bSemanticId:p.bSemanticId});renderDrawer()}
