function openHashWish(){if(!location.hash.startsWith('#wish='))return false;const id=decodeURIComponent(location.hash.slice(6));if(!byId.has(id))return false;if(hashOpenedId!==id){hashOpenedId=id;navigateWish(id)}else send({type:'rv25-focus',semanticId:id});return true}
function renderWish(){const m=current;if(!m)return'';const root=rootFor(m),parent=parentFor(m),directChildren=semantic.filter(x=>x.parentSemanticId===m.semanticId),branches=childrenOf(m,'split').length,continued=childrenOf(m,'evolve').length>0,enc=isEncouraged(m.semanticId);const chips=[kindLabel(m.kind),formatState(m),branches?countLabel(branches,'branchCount','branchesCount'):null,m.helpCount?countLabel(m.helpCount,'helpOne','helpCount'):null,m.warpCount?countLabel(m.warpCount,'connectOne','connectCount'):null].filter(Boolean);let main='',more='';if(m.owner){if(m.state==='alive'){if(!continued)main+=`<button data-act="evolve">${T('evolve')}</button>`;main+=`<button data-act="${branches?'branch':'split'}">${branches?T('addBranch'):T('split')}</button><button data-act="bloom">${m.kind==='create'?T('bloomWish'):T('bloomBranch')}</button>`}if(m.state==='abandoned')main+=m.kind==='create'?`<button data-act="resume_lineage">${T('resumeWish')}</button>`:`<button data-act="resume">${T('resume')}</button>`;main+=`<button data-act="focus">${T('focus')}</button>`;more=`<button data-act="correct">${T('correct')}</button>${m.kind!=='create'&&m.state==='alive'?`<button data-act="reattach">${T('reattach')}</button>`:''}${m.state==='alive'&&!SOLO?`<button data-act="connect">${T('connect')}</button>`:''}${m.state==='alive'?(m.kind==='create'?`<button class="danger" data-act="close_lineage">${T('closeWish')}</button>`:`<button class="danger" data-act="abandon">${T('abandon')}</button>`):''}${m.state==='alive'?`<button class="danger" data-act="remove">${T('remove')}</button>`:''}<button data-act="share">${T('share')}</button>`}else{if((SHARED||SOLO)&&m.simulated){main=`<button data-act="focus">${T('focus')}</button>`;more=''}else{if(m.state==='alive')main=`<button data-act="encourage" ${enc?'disabled':''}>${enc?T('encouraged'):T('encourage')}</button><button data-act="help">${T('help')}</button><button data-act="suggest">${T('suggest')}</button>`;main+=`<button data-act="focus">${T('focus')}</button>`;more=`${m.state==='alive'?`<button data-act="connect">${T('connect')}</button>`:''}<button data-act="share">${T('share')}</button>${m.simulated?'':`<button class="danger" data-act="report">${T('report')}</button>`}`}}const nav=(parent||directChildren.length)?`<div class="wish-nav">${parent?`<button class="wish-nav-parent" data-nav-wish="${esc(parent.semanticId)}"><span>${T('parentWish')}</span><b>↑ ${esc(parent.text)}</b></button>`:''}${directChildren.length?`<div class="wish-nav-label">${T('subWishes')}</div>${directChildren.map(x=>`<button data-nav-wish="${esc(x.semanticId)}"><span>${esc(formatState(x))}</span><b>${esc(x.text)}</b></button>`).join('')}`:''}</div>`:'';return`<div class="drawer-kicker">${m.owner?T('mine'):(m.simulated?T('simulated'):T('human'))} · ${esc(formatState(m))}</div><div class="wish">${esc(m.text)}</div><div class="meta">${m.loc?esc(m.loc)+'<br>':''}${T('origin')}: ${esc(root.text)}${parent?`<br>${T('from')}: ${esc(parent.text)}`:''}</div>${nav}<div class="chips">${chips.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="action-grid">${main}</div>${more?`<details class="more"><summary>${T('more')}</summary><div class="more-grid">${more}</div></details>`:''}`}
function proposalLabel(p){const st=proposalStatus(p);if(!proposalTargetAlive(p))return T('expired');return T(st)}
function proposalTitle(p){if(p.type==='connect_proposed')return T('connectReceived');if(p.type==='help_proposed')return T('helpReceived');return T('suggestReceived')}
