function createModal(){modal(T('release'),`<p>${T('createHint')}</p><div class="field"><label>${T('wish')}</label><textarea id="wishInput" maxlength="280"></textarea></div><div class="field"><label>${T('location')}</label><input id="locInput" maxlength="80" autocomplete="off" placeholder="${T('locationPlaceholder')}"><div id="locStatus" class="field-note">${T('locating')}</div></div>`,`<button id="cancel">${T('cancel')}</button><button id="confirm" class="primary">${T('create')}</button>`);const input=document.getElementById('locInput'),status=document.getElementById('locStatus');prefillCurrentLocation(input,status);document.getElementById('cancel').onclick=closeOverlay;document.getElementById('confirm').onclick=()=>{const text=document.getElementById('wishInput').value.trim(),loc=input.value.trim();if(!text){toast(T('required'));return}if(!loc){toast(T('locationRequired'));input.focus();return}const lineageId=uid('lineage'),semanticId=uid('wish');closeOverlay();commit({type:'create',lineageId,semanticId,text,loc,seed:seed(lineageId)},semanticId)}}
