function proposeConnection(target){if(!connectSource)return;const source=connectSource;if(source.lineageId===target.lineageId){toast(T('sameLineage'));return}const aOwner=ownerActor(source)||'external:'+source.lineageId,bOwner=ownerActor(target)||'external:'+target.lineageId,requiredActors=[...new Set([aOwner,bOwner])],proposalId=uid('connect');modal(T('connectAsk'),`<p><b>${esc(source.text)}</b><br>↔<br><b>${esc(target.text)}</b></p><p>${T('connectPending')}</p>`,`<button id="cancel">${T('cancel')}</button><button id="confirm" class="primary">${T('connect')}</button>`);document.getElementById('cancel').onclick=()=>{closeOverlay();cancelConnect()};document.getElementById('confirm').onclick=()=>{closeOverlay();hideMode();connectSource=null;const p=commit({type:'connect_proposed',proposalId,aSemanticId:source.semanticId,bSemanticId:target.semanticId,requiredActors,seed:seed(proposalId)});if(!SHARED&&requiredActors.includes(PERSONA))commit({type:'proposal_response',proposalId,decision:'accept'});materialize(p);toast(T('connectPending'))}}
