function correctModal(m){modal(T('correctTitle'),`<p>${T('correctHint')}</p><div class="field"><label>${T('wish')}</label><textarea id="correctText" maxlength="280">${esc(m.text)}</textarea></div><div class="field"><label>${T('location')}</label><input id="correctLoc" maxlength="80" value="${esc(m.loc||'')}"></div>`,`<button id="cancel">${T('cancel')}</button><button id="confirm" class="primary">${T('correct')}</button>`);document.getElementById('cancel').onclick=closeOverlay;document.getElementById('confirm').onclick=()=>{const text=document.getElementById('correctText').value.trim(),loc=document.getElementById('correctLoc').value.trim();if(!text){toast(T('required'));return}if(text===m.text.trim()&&loc===(m.loc||'')){toast(T('nothingChanged'));return}closeOverlay();commit({type:'correct',semanticId:m.semanticId,text,loc,seed:seed('correct|'+m.semanticId+'|'+text+'|'+loc)},m.semanticId)}}
function reattachModal(m){const desc=descendants(m),opts=lineage(m).filter(x=>x.semanticId!==m.semanticId&&!desc.has(x.semanticId)&&x.state==='alive');if(!opts.length){toast(T('noParent'));return}modal(T('reattachTitle'),`<p>${T('reattachHint')}</p><div class="field"><select id="parentSelect">${opts.map(x=>`<option value="${esc(x.semanticId)}">${esc(x.text)}</option>`).join('')}</select></div>`,`<button id="cancel">${T('cancel')}</button><button id="confirm" class="primary">${T('reattach')}</button>`);document.getElementById('cancel').onclick=closeOverlay;document.getElementById('confirm').onclick=()=>{const newParentSemanticId=document.getElementById('parentSelect').value;closeOverlay();commit({type:'reparent',semanticId:m.semanticId,newParentSemanticId,seed:seed('reparent|'+m.semanticId+'|'+newParentSemanticId)},m.semanticId)}}
function removeMistake(m){
  if(SHARED&&typeof window.__RALUVAAA_SHARED_REMOVE__==='function'){
    if(!confirm(T('removeAsk')))return;
    Promise.resolve(window.__RALUVAAA_SHARED_REMOVE__(m.semanticId)).then(()=>{window.dispatchEvent(new CustomEvent('raluvaaa-remove',{detail:{semanticId:m.semanticId}}));toast(T('removed'))}).catch(err=>{console.error(err);toast(SHARED&&typeof window.__RALUVAAA_SHARED_ERROR__==='function'?window.__RALUVAAA_SHARED_ERROR__(err):String(err?.message||err))});
    return
  }
  if(m.state!=='alive'){toast(T('removeOnlyFresh'));return}
  const hasDesc=[...descendants(m)].some(id=>id!==m.semanticId);
  const hasExternal=state.events.some(e=>(e.type==='encourage'||e.type==='help'||e.type==='connect'||e.type==='help_proposed'||e.type==='suggest_proposed'||e.type==='connect_proposed')&&(e.semanticId===m.semanticId||e.aSemanticId===m.semanticId||e.bSemanticId===m.semanticId));
  if(hasDesc||hasExternal){toast(T('removeHasDesc'));return}
  if(!confirm(T('removeAsk')))return;
  window.dispatchEvent(new CustomEvent('raluvaaa-remove',{detail:{semanticId:m.semanticId}}));
  state.events=state.events.filter(e=>e.semanticId!==m.semanticId&&!(e.type==='create'&&e.semanticId===m.semanticId));
  save();closeDrawer();send({type:'rv25-rebuild',events:state.events});toast(T('removed'));updateAll()
}
async function share(m){let id=m.semanticId;if(SHARED&&typeof window.__RALUVAAA_SHARED_SHARE__==='function'){try{id=await window.__RALUVAAA_SHARED_SHARE__(id)}catch{}}const u=new URL(location.href);u.hash='wish='+encodeURIComponent(id);window.dispatchEvent(new CustomEvent('raluvaaa-share'));navigator.clipboard?.writeText(u.href).then(()=>toast(T('copied'))).catch(()=>prompt(T('copyPrompt'),u.href))}
function focusLineage(m){focusLineageId=m.lineageId;document.body.dataset.focusLineage=m.lineageId;closeDrawer();showMode(`${T('lineageMode')}: ${rootFor(m).text}`,exitFocus);send({type:'rv25-lineage-focus',lineageId:m.lineageId})}
function exitFocus(){focusLineageId=null;delete document.body.dataset.focusLineage;hideMode();send({type:'rv25-lineage-focus',lineageId:null})}
function entrustedDuration(slot,now,nonce){const ranges=[[3*HOUR,8*HOUR],[18*HOUR,30*HOUR],[60*HOUR,84*HOUR]],r=ranges[slot]||ranges[2],span=r[1]-r[0],n=seed('entrusted-duration|'+slot+'|'+now+'|'+nonce);return r[0]+(n%Math.max(1,span))}
function ensureEntrusted(){const simulated=semantic.filter(m=>m.simulated&&m.kind==='create'),realForeign=semantic.filter(m=>SHARED&&!m.simulated&&!owned(m)&&m.kind==='create'),roots=SHARED?[...realForeign,...simulated]:simulated;if(!roots.length)return;const now=Date.now();let changed=false;let slots=Array.isArray(state.entrusted)&&state.entrusted.length===3?state.entrusted.map(x=>({...x})):Array(3).fill(null);const active=new Set(slots.filter(x=>x&&x.expires>now&&byId.has(x.semanticId)).map(x=>x.semanticId));for(let i=0;i<3;i++){const cur=slots[i],valid=cur&&cur.expires>now&&byId.has(cur.semanticId);if(valid)continue;const previous=cur?.semanticId||null,candidates=roots.filter(r=>!active.has(r.semanticId)&&r.semanticId!==previous);const pool=candidates.length?candidates:roots.filter(r=>!active.has(r.semanticId));if(!pool.length)continue;const nonce=(cur?.nonce||0)+1,idx=seed('entrusted-pick|'+i+'|'+now+'|'+nonce)%pool.length,pick=pool[idx];slots[i]={semanticId:pick.semanticId,expires:now+entrustedDuration(i,now,nonce),nonce};active.add(pick.semanticId);changed=true}state.entrusted=slots;if(changed)save();updateBadges()}
